const portrait=key=>['maker','coach','rook'].includes(key)?`<span class="ow-portrait" aria-hidden="true"><img src="/world-assets/${key}.webp" alt="" draggable="false"></span>`:`<span class="ow-portrait ow-atlas ow-${key}" aria-hidden="true"></span>`;
const mark=p=>['slack','teams'].includes(p.service)?`<img class="ow-brand" src="/world-assets/${p.service}.svg" alt="">`:'';
const placeArt=p=>`<span class="ow-place-art ow-art-${['slack','teams','minecraft'].includes(p.service)?p.service:'other'}" aria-hidden="true"></span>`;
