let auth={},view=null,raw={endpoints:[],hosts:[],places:[],jobs:[]},catalogs={},model=project(raw),layout={},camera={x:0,y:0,scale:1},modal=null,selected=null,currentPlace=null,currentRoom=null,profilePlace=null,roomPage=0,invitePage=0,rosterPages={},returnKey='add',draft={},journal={},loading=false,writing=false,initialFit=true,drag=null,suppressClick=false,saveTimer=null,refreshTimer=null;
let serial=Promise.resolve();
let pairing={record:null,downloads:[],platform:'',requestId:null,error:'',loading:false,uncertain:false,network:null,networkRequest:null,networkUncertain:false},pairingTimer=null;
class ApiError extends Error{constructor(message,status){super(message);this.status=status}}
async function api(path,method='GET',body){const response=await fetch(path.startsWith('/')?path:'/api/v1/'+path,{method,headers:{'Content-Type':'application/json',...(auth.csrf?{'X-CSRF-Token':auth.csrf}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});let value;try{value=await response.json()}catch{throw new ApiError('The service returned an unreadable response.',response.status)}if(!response.ok)throw new ApiError(value.error||`Request failed (${response.status})`,response.status);return value}
function notice(message,error=false){const n=q('#ow-message');if(n){n.textContent=message;n.classList.toggle('ow-error',error)}}
function run(action){const task=serial.then(async()=>{writing=true;try{await action()}catch(e){notice(e.message,true);const error=q('#ow-form-error');if(error)error.textContent=e.message}finally{writing=false}});serial=task.catch(()=>{});return task}
const agent=id=>model.agents.find(a=>a.id===(id||selected));
const machine=id=>model.machines.find(m=>m.id===id);
const place=id=>model.places.find(p=>p.id===(id||currentPlace));
const room=()=>place()?.rooms.find(r=>r.id===currentRoom)||place()?.rooms[0];
const pairingKey=()=>`observatory-pairing:${location.origin}:${auth.owner}`;
function rememberPairing(id){pairing.requestId=id;sessionStorage.setItem(pairingKey(),id)}
function pairingState(){const p=pairing.record;return p?.state==='waiting'&&p.expires_at<=Date.now()?'expired':p?.state||null}
function pairingHost(){return raw.hosts.find(h=>h.id===pairing.record?.host_id)}
function setupUrl(download){try{const u=new URL(download.url,location.origin),prefix=`/api/v1/machine-pairings/${pairing.record.id}/setup/`;return u.origin===location.origin&&u.pathname===prefix+download.platform?u.href:null}catch{return null}}
function acceptPairing(value){pairing.record=value.pairing;pairing.downloads=value.downloads||value.pairing?.downloads||pairing.downloads;if(pairing.record?.id)rememberPairing(pairing.record.id);if(!pairing.downloads.some(d=>d.platform===pairing.platform))pairing.platform=pairing.downloads[0]?.platform||'';pairing.uncertain=false;pairing.error=''}
function schedulePairing(){clearTimeout(pairingTimer);if(modal==='pair-computer'&&['waiting','paired'].includes(pairingState()))pairingTimer=setTimeout(()=>run(()=>readPairing(false)),5000)}
async function readPairing(list=false){pairing.loading=true;if(modal==='pair-computer')renderPopup();try{pairing.network=await api('machine-network');if(pairing.networkRequest?.request_id===pairing.network.request_id){pairing.networkRequest=null;pairing.networkUncertain=false;sessionStorage.removeItem(pairingKey()+':network')}else if(pairing.networkRequest&&pairing.network.revision>pairing.networkRequest.expected_revision){pairing.networkRequest=null;pairing.networkUncertain=false;sessionStorage.removeItem(pairingKey()+':network')}if(list||!pairing.requestId){const value=await api('machine-pairings');pairing.downloads=value.downloads||[];const remembered=sessionStorage.getItem(pairingKey()),record=value.pairings?.find(p=>p.id===remembered)||value.pairings?.find(p=>p.state==='waiting');if(record)rememberPairing(record.id);else pairing.requestId=remembered||null;if(!pairing.downloads.some(d=>d.platform===pairing.platform))pairing.platform=pairing.downloads[0]?.platform||''}if(pairing.requestId){try{acceptPairing(await api('machine-pairings/'+encodeURIComponent(pairing.requestId)))}catch(e){if(e.status!==404)throw e;pairing.record=null;pairing.uncertain=false;pairing.error='Setup was not found. Get setup to try the same request again.'}}else{pairing.record=null;pairing.error='';pairing.uncertain=false}if(pairingState()==='paired')await refresh()}catch(e){pairing.error='Could not check pairing. '+e.message;pairing.uncertain=true}finally{pairing.loading=false;if(modal==='pair-computer')renderPopup();schedulePairing()}}
async function startPairing(fresh=false){if(pairing.loading||pairingState()==='waiting'||(pairingState()==='paired'&&!fresh))return;if(!pairing.platform)throw Error('No computer setup downloads are available yet.');if(fresh||!pairing.requestId){rememberPairing(crypto.randomUUID());pairing.record=null}pairing.loading=true;pairing.error='';renderPopup();try{acceptPairing(await api('machine-pairings','POST',{request_id:pairing.requestId,install_agents:true}))}catch(e){const refused=e.status>=400&&e.status<500&&e.status!==408;pairing.error=refused?e.message:'Setup was not confirmed. Check its status before continuing.';pairing.uncertain=!refused}finally{pairing.loading=false;renderPopup();schedulePairing()}}
async function cancelPairing(){if(pairingState()!=='waiting')return;try{acceptPairing(await api('machine-pairings/'+pairing.record.id+'/cancel','POST',{}));if(pairingState()==='paired')await refresh()}catch(e){pairing.error='Cancellation was not confirmed. Check its status before continuing.';pairing.uncertain=true}renderPopup();schedulePairing()}
async function changeNetwork(enabled,retry=false){
 if(pairing.loading||(pairing.networkUncertain&&!retry))return;
 const address=enabled?(q('[data-control=network-address]')?.value||pairing.network?.address||pairing.network?.addresses?.[0]?.address):pairing.network?.address;
 const body=retry?pairing.networkRequest:{request_id:crypto.randomUUID(),expected_revision:pairing.network?.revision||0,enabled,address:address||null};if(!body)return;
 pairing.networkRequest=body;sessionStorage.setItem(pairingKey()+':network',JSON.stringify(body));pairing.loading=true;pairing.error='';renderPopup();
 try{pairing.network=await api('machine-network','POST',body);pairing.networkUncertain=false;pairing.networkRequest=null;sessionStorage.removeItem(pairingKey()+':network')}
 catch(e){pairing.networkUncertain=!(e.status>=400&&e.status<500&&e.status!==408);pairing.error=pairing.networkUncertain?'The network change was not confirmed. Check status before continuing.':e.message;if(!pairing.networkUncertain){pairing.networkRequest=null;sessionStorage.removeItem(pairingKey()+':network')}}
 finally{pairing.loading=false;renderPopup()}
}
function networkPanel(){
 const n=pairing.network;if(!n||n.mode!=='local')return '';
 if(pairing.networkUncertain)return `<h3>Check your network setup</h3><p>The last change was not confirmed. Check its status, or retry that same request.</p><div class="ow-dialog-actions">${button('Check again','pair-refresh',pairing.loading?'disabled':'','ow-button ow-primary')}${button('Try the same setup again','network-retry',pairing.loading?'disabled':'')}</div>`;
 if(n.available)return `<p class="ow-help">This network is ready for your computer helper.</p><details><summary>Network access</summary><p class="ow-help">Helpers connect to ${esc(n.endpoint)}. Turning this off pauses computer status here. Your agents keep working.</p>${button('Turn off network access','network-disable',pairing.loading?'disabled':'')}</details>`;
 let html='<h3>Let your computers connect</h3><p>Use a network these computers share, such as your home network or private network. Your Observatory browser stays on this computer.</p>';
 const choices=n.addresses||[];
 if(choices.length>1)html+=`<label class="ow-pair-platform">Network address<select data-control="network-address">${choices.map(a=>`<option value="${esc(a.address)}" ${a.address===n.address?'selected':''}>${esc(a.label)}</option>`).join('')}</select></label>`;
 else if(choices.length===1)html+=`<p class="ow-help">${esc(choices[0].label)}</p>`;
 else html+='<p>Connect this computer to a network, then check again.</p>';
 if(n.error)html+=`<p class="ow-warning" role="alert">${esc(n.error)}</p>`;
 html+=`<div class="ow-dialog-actions">${pairing.networkUncertain?button('Try the same setup again','network-retry',pairing.loading?'disabled':'','ow-button ow-primary'):button(pairing.loading?'Setting up…':'Use this network','network-enable',pairing.loading||!choices.length?'disabled':'','ow-button ow-primary')}${button('Check again','pair-refresh',pairing.loading?'disabled':'')}</div>`;
 return html;
}
function pairedComputerStatus(host){const m=host?.machine;if(!m)return '';const state=m.state,label=state==='online'?'Computer connected':state==='disconnected'?'Pairing disconnected':'Computer not reachable';return `<div class="ow-machine-state"><strong>${label}</strong><p>${m.last_seen_at?'Last seen '+esc(when(m.last_seen_at)):'Waiting for the first update from this computer.'}</p>${state==='offline'?'<p>It may be sleeping or offline. Its agents keep working independently.</p>':state==='disconnected'?'<p>This computer no longer reports to Observatory. Its agents and files are unchanged.</p>':(host?.recipes?.some(r=>r.id==='paired-instance')?'<p>You can add agents here. Each agent keeps its own settings and connections.</p>':'<p>This computer reports when it is available. Open its helper to allow agent setup, or connect an existing agent.</p>')}</div>`}
function pairingPanel(){const state=pairingState(),p=pairing.record,host=pairingHost(),downloads=pairing.downloads.filter(d=>!p||setupUrl(d)),download=downloads.find(d=>d.platform===pairing.platform),busy=pairing.loading;let content=heading('Add a computer','Pair it once with your constellation.');
 if(pairing.network?.mode==='local'&&!pairing.network.available)return content+networkPanel()+(pairing.error?`<p class="ow-warning" role="alert">${esc(pairing.error)}</p>`:'');
 if(state==='paired'){const online=host?.machine?.state==='online';return heading(host?.machine?.state==='disconnected'?'Pairing disconnected':online?'Computer connected':'Computer paired',host?.label||'Waiting for the first update.')+`<div class="ow-machine-preview" aria-hidden="true"></div>${pairedComputerStatus(host)||'<p>Pairing was accepted. Waiting for the computer to report its availability.</p>'}<div class="ow-dialog-actions">${host?button('Show computer','show-paired-computer',`data-machine="${esc(host.id)}"`,'ow-button ow-primary'):button('Check status','pair-refresh','','ow-button ow-primary')}${button(host?.machine?.state==='disconnected'?'Get new setup':'Pair another computer','pair-new',busy?'disabled':'')}</div>`}
 if(state==='expired'||state==='cancelled'||state==='locked'){return content+`<div class="ow-machine-preview" aria-hidden="true"></div><h3>${state==='expired'?'This code has expired':state==='locked'?'This code is no longer available':'Pairing cancelled'}</h3><p>${state==='expired'?'The code can no longer connect a computer. Get a new setup when you are ready.':state==='locked'?'There were too many incorrect attempts. Get a new setup to pair your computer.':'This code no longer works. Cancelling it did not connect or disconnect a computer.'}</p><div class="ow-dialog-actions">${button('Get new setup','pair-new',busy?'disabled':'','ow-button ow-primary')}</div>${pairing.error?`<p class="ow-warning" role="alert">${esc(pairing.error)}</p>`:''}`}
 content+=networkPanel();
 content+=`<div class="ow-pair-intro"><div class="ow-mini-computer" aria-hidden="true"></div><p>Open a small helper on the computer you want to add. ${download?.installation_protocol===1?'Use the code below to connect it and allow Observatory to add agents.':'Use the code below to confirm the connection there.'}</p></div>`;
 if(downloads.length)content+=`<label class="ow-pair-platform">That computer uses<select data-control="pair-platform" data-key="pair-platform">${downloads.map(d=>`<option value="${esc(d.platform)}" ${d.platform===pairing.platform?'selected':''}>${esc(d.label)}${d.architecture?' — '+esc(d.architecture):''}</option>`).join('')}</select></label>`;
 else if(!busy)content+='<p>Computer setup downloads are not available from this Observatory yet.</p>';
 if(state==='waiting'){const url=download&&setupUrl(download);content+=`<ol class="ow-pair-steps"><li>${url?`<a class="ow-button ow-primary" href="${esc(url)}" download="${esc(download.filename||'')}">Download for ${esc(download.label)}</a>`:'Choose an available setup download.'}<p>Extract the download on that computer, then open the app inside.</p>${/^(windows|macos)-/.test(download?.platform||'')?'<p class="ow-help">Preview download — Windows and Mac apps are not yet signed.</p>':''}</li><li><p>Enter this code in the helper, then choose Pair.</p><div class="ow-pair-code"><output aria-label="Pairing code">${esc(p.code)}</output>${button('Copy code','pair-copy','data-key="pair-copy"')}</div><p class="ow-muted">Expires at ${esc(new Date(p.expires_at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}))}.</p></li></ol><p class="ow-pair-wait" role="status">Waiting for your computer…</p><p class="ow-help">Keep the computers on the same network, or connected through your private network.</p><div class="ow-dialog-actions">${button('Check status','pair-refresh',busy?'disabled':'')}${button('Cancel pairing','pair-cancel',busy?'disabled':'')}</div>`}
 else content+=`<div class="ow-dialog-actions">${pairing.uncertain?button('Check status','pair-refresh',busy?'disabled':'','ow-button ow-primary'):button(busy?'Getting setup…':'Get setup','pair-start',busy||!downloads.length?'disabled':'','ow-button ow-primary')}</div>`;
 if(pairing.error)content+=`<p class="ow-warning" role="alert">${esc(pairing.error)}</p>`;
 return content+`<div class="ow-pair-advanced">${button('Use configured local or SSH access','create-machine','','ow-place-link')}</div>`}
const journalKey=()=>`observatory-operations:${location.origin}:${auth.owner}`;
function loadJournal(){const prefix=journalKey()+':',next={};for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(!key.startsWith(prefix))continue;try{const j=JSON.parse(localStorage.getItem(key));if(j?.body?.request_id&&!localStorage.getItem(prefix+'done:'+j.body.request_id))next[j.body.request_id]=j}catch{}}journal=next}
function saveJournal(){for(const [id,j] of Object.entries(journal)){const key=journalKey()+':'+id;if(!localStorage.getItem(journalKey()+':done:'+id))localStorage.setItem(key,JSON.stringify(j))}loadJournal()}
function finishJournal(id){localStorage.setItem(journalKey()+':done:'+id,JSON.stringify({settled:true,at:Date.now()}));delete journal[id]}
function pendingFor(id){return Object.values(journal).find(j=>j.endpoint_id===id&&!j.rejected)}
function pendingStatus(b){const pending=Object.values(journal).find(j=>j.endpoint_id===b.agentId&&j.body?.connection_id===b.connectionId);return pending?{label:pending.uncertain?'Request outcome not confirmed':'Change requested…',pending:true,connected:false,uncertain:pending.uncertain}:b.status}
function ops(id,operation,body={}){return api(`endpoints/${id}/operations/${operation}`,'POST',body)}
async function saveView(){if(!view)return;const next={camera,positions:layout,machine_id:agent()?.machineId===UNASSIGNED?null:agent()?.machineId||null,place_id:currentPlace||null,room_id:currentRoom||null,navigation:currentPlace?'place':'world'};try{view=await api(`views/${view.id}/commands`,'POST',{expected_revision:view.revision,controller:'human',commands:[{op:'set',field:'screen',value:'world'},{op:'set',field:'selected_id',value:selected||null},{op:'set',field:'world',value:next}]})}catch(e){if(e.status===409){view=await api(`views/${view.id}`);applyView();render();notice('This view changed elsewhere. The latest arrangement is shown.');return}throw e}}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{saveTimer=null;run(saveView)},150)}
function applyView(){const w=view?.world||{};layout={...(w.positions||{})};camera={x:0,y:0,scale:1,...w.camera};selected=model.agents.some(a=>a.id===view?.selected_id)?view.selected_id:null;currentPlace=model.places.some(p=>p.id===w.place_id)?w.place_id:null;currentRoom=currentPlace?w.room_id:null}
function shell(){root.innerHTML=`<header class="ow-top"><div class="ow-title"><h1>Observatory</h1></div><span class="ow-owner">${esc(auth.owner)}’s constellation</span><div class="ow-top-actions">${button('Refresh','refresh','data-key="refresh"')}${button('+ Add','add','data-key="add"','ow-button ow-primary')}<a class="ow-advanced" href="/advanced">Advanced controls</a>${button('Sign out','logout','','ow-signout')}</div></header><div id="ow-toolbar" class="ow-toolbar"></div><div id="ow-viewport" class="ow-viewport" aria-label="Pan and zoom canvas"><div id="ow-plane" class="ow-plane"><svg class="ow-links" aria-hidden="true"><g></g></svg><section id="ow-machines" class="ow-machines" aria-label="Computers"></section><section id="ow-destinations" class="ow-destinations" aria-label="Places"></section></div><div class="ow-canvas-hint">Drag the canvas to explore. Drag a nameplate to arrange.</div><div id="ow-empty-world"></div></div><section id="ow-inside" class="ow-inside" hidden></section><div class="ow-status"><span id="ow-message" role="status" aria-live="polite">Reading your installations…</span><span id="ow-refreshed"></span></div><dialog id="ow-dialog" class="ow-dialog"><div id="ow-dialog-body"></div></dialog>`;q('#ow-dialog').addEventListener('close',()=>{clearTimeout(pairingTimer);modal=null;(q(`[data-key="${CSS.escape(returnKey)}"]`)||q('[data-key=add]'))?.focus({preventScroll:true})});bindCanvas()}
async function loadCatalog(id){const old=catalogs[id];try{const data=await ops(id,'service-connections');catalogs[id]={data,checkedAt:Date.now(),error:null};for(const [key,j] of Object.entries(journal)){if(j.endpoint_id!==id)continue;const op=operationMatch(data,j.body.request_id);if(op?.finished_at){finishJournal(key);notice((op.result?.failed||op.result?.state==='failed')?'The installation reported a failed change. Check its connection details.':'The installation finished the connection change.')}else if(op){j.uncertain=false}}saveJournal()}catch(e){catalogs[id]={...old,error:e.message,checkedAt:Date.now()}}}
async function refresh(inspect=false){if(loading)return;loading=true;try{const keys=['endpoints','hosts','places','jobs'];await Promise.all(keys.map(async key=>{try{const value=await api(key);raw[key]=value[key]||[]}catch(e){if(key!=='jobs')throw e}}));const targets=raw.endpoints.filter(e=>(e.kind==='agent'||!e.kind)&&e.management?.provider==='agent-instance');let cursor=0;await Promise.all(Array.from({length:Math.min(4,targets.length)},async()=>{while(cursor<targets.length){const e=targets[cursor++];if(inspect){try{const o=await api(`endpoints/${e.id}/inspect`,'POST',{});e.observation=o}catch{}}await loadCatalog(e.id)}}));model=project({...raw,catalogs});const defaults=defaultLayout(model);for(const [id,p] of Object.entries(defaults))if(!layout[id])layout[id]=p;if(selected&&!agent())selected=null;if(currentPlace&&!place())currentPlace=null;render();q('#ow-refreshed').textContent='Checked '+new Date().toLocaleTimeString();}catch(e){notice('Could not refresh: '+e.message+'. Previously observed information may be out of date.',true)}finally{loading=false}}
function position(id){return layout[id]||defaultLayout(model)[id]||{x:40,y:40}}
function render(){if(!view||!q('#ow-plane'))return;const activeKey=document.activeElement?.dataset?.key;q('#ow-toolbar').innerHTML=currentPlace?`${button('← My constellation','back','data-key="back"')}<span class="ow-inside-title">${mark(place())}${esc(place().name)}</span>`:`<label><span class="ow-sr">Find on canvas</span><select data-control="jump" data-key="jump" aria-label="Find on canvas"><option value="">Find on canvas…</option><optgroup label="Computers">${model.machines.map(m=>`<option value="machine:${m.id}">${esc(m.name)}</option>`).join('')}</optgroup><optgroup label="Places">${model.places.map(p=>`<option value="place:${p.id}">${esc(p.name)}</option>`).join('')}</optgroup></select></label><div class="ow-camera-controls">${button('−','zoom-out','aria-label="Zoom out"','')}<span class="ow-zoom-value">${Math.round(camera.scale*100)}%</span>${button('+','zoom-in','aria-label="Zoom in"','')}${button('Fit view','fit','data-key="fit"','ow-fit')}</div>`;
q('#ow-machines').innerHTML=model.machines.map(m=>{const all=model.agents.filter(a=>a.machineId===m.id),pages=Math.max(1,Math.ceil(all.length/12)),page=Math.min(rosterPages[m.id]||0,pages-1);return `<article class="ow-machine${all.length>4?' ow-dense':''}${m.unassigned?' ow-unassigned':''}" data-node="machine:${m.id}" data-computer="${m.id}"><div class="ow-machine-image"></div>${button(`<span>${esc(m.name)}<small>${all.length} ${all.length===1?'agent':'agents'}</small></span>`,'machine',`data-machine="${m.id}" data-drag-node="machine:${m.id}" data-key="machine-${m.id}" aria-label="Open ${esc(m.name)}. Drag to arrange."`,'ow-machine-header')}<div class="ow-crew">${all.slice(page*12,(page+1)*12).map(a=>button(portrait(a.portrait)+`<span class="ow-agent-name">${esc(a.name)}</span>`,'agent',`data-agent="${a.id}" data-key="agent-${a.id}" aria-pressed="${a.id===selected}" aria-label="Open ${esc(a.name)}"`,'ow-agent')).join('')||'<p class="ow-empty">No agents assigned</p>'}</div><div class="ow-machine-tools">${pages>1?button('←','roster-page',`data-machine="${m.id}" data-page="${page-1}" ${page===0?'disabled':''} aria-label="Previous agents"`,'')+`<span>${page+1}/${pages}</span>`+button('→','roster-page',`data-machine="${m.id}" data-page="${page+1}" ${page===pages-1?'disabled':''} aria-label="Next agents"`,''):''}${!m.unassigned?(m.host?.recipes?.length?button('+ Agent','create-agent',`data-machine="${m.id}"`,''):button('+ Existing agent','attach',`data-machine="${m.id}"`,'')):button('Assign computers','machine',`data-machine="${m.id}"`,'')}</div></article>`}).join('');
q('#ow-destinations').innerHTML=model.places.map(p=>{const active=p.bindings.some(b=>b.agentId===selected&&pendingStatus(b).connected),count=p.bindings.filter(b=>pendingStatus(b).connected).length;return `<article class="ow-place${active?' connected':''}" data-node="place:${p.id}">${button(placeArt(p)+`<span class="ow-place-caption">${esc(p.service)} · ${count} connected</span>`,'enter',`data-place="${esc(p.id)}" data-key="enter-${esc(p.id)}" aria-label="Enter ${esc(p.name)}"`,'ow-place-open')}${button(mark(p)+esc(p.name),'enter',`data-place="${esc(p.id)}" data-drag-node="place:${esc(p.id)}"`,'ow-place-move')}</article>`}).join('');
q('#ow-viewport').hidden=!!currentPlace;q('#ow-inside').hidden=!currentPlace;
if(currentPlace){q('#ow-inside').dataset.kind=place().kind;q('#ow-inside').innerHTML=inside()}
q('#ow-empty-world').innerHTML=!model.agents.length&&!model.machines.length?`<div class="ow-empty-canvas"><h2>Bring your constellation into view</h2><p>Add a computer or connect an existing agent.</p>${button('+ Add','add','','ow-button ow-primary')}</div>`:'';
for(const n of q('#ow-plane').querySelectorAll('[data-node]')){const p=position(n.dataset.node);n.style.left=p.x+'px';n.style.top=p.y+'px'}
applyCamera();if(modal&&!['attach','create-agent','create-machine','service-add','assign','pair-computer','disconnect-machine'].includes(modal))renderPopup();if(activeKey&&!q('#ow-dialog').open)q(`[data-key="${CSS.escape(activeKey)}"]`)?.focus({preventScroll:true});requestAnimationFrame(()=>{if(initialFit&&!currentPlace&&model.machines.length){initialFit=false;if(camera.x===0&&camera.y===0&&camera.scale===1){if(root.clientWidth<600)focusNode('machine:'+model.machines[0].id,false);else fit(false)}}paths()})}
function inside(){const p=place(),r=room();currentRoom=r.id;const rows=p.bindings.filter(b=>b.roomId===r.id),size=root.clientWidth<500?6:8,pages=Math.max(1,Math.ceil(rows.length/size));roomPage=Math.min(roomPage,pages-1);return `${p.rooms.length>1?`<nav class="ow-room-tabs" aria-label="Rooms">${p.rooms.map(x=>button(esc(x.label),'room',`data-room="${esc(x.id)}" aria-pressed="${x.id===r.id}"`,'ow-room-tab')).join('')}</nav>`:''}<div class="ow-room-sign"><h2>${esc(p.kind==='server'?p.name:r.label)}</h2><p>${p.kind==='workspace'?'Workspace connections. Individual channel membership stays in '+esc(p.service)+'.':p.kind==='server'?'Agents connected to this server':'Saved connections owned by each installation'}</p></div><div class="ow-room-floor">${rows.slice(roomPage*size,(roomPage+1)*size).map(b=>{const a=agent(b.agentId),status=pendingStatus(b);return button(portrait(a.portrait)+`<span class="ow-room-agent-label">${esc(a.name)}<small>${esc(machine(a.machineId)?.name)} · ${esc(status.label)}</small></span>`,'agent',`data-agent="${a.id}" data-key="inside-${a.id}"`,'ow-room-agent'+(status.connected?'':' ow-offline'))}).join('')||'<div class="ow-room-empty">No saved connections are assigned here yet.</div>'}</div><div class="ow-room-footer"><p>${rows.filter(b=>pendingStatus(b).connected).length} connected · ${rows.length} saved</p>${pages>1?pagination('room-page',roomPage,pages):''}${button('Add agents','invite','data-key="invite"','ow-button ow-primary')}</div>`}
function heading(title,sub=''){return `<div class="ow-dialog-head"><div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div>${button('×','close','aria-label="Close popup" data-key="close"','ow-button ow-icon')}</div>`}
function field(label,name,value='',extra=''){return `<label>${esc(label)}<input name="${esc(name)}" value="${esc(value)}" ${extra}></label>`}
function selector(label,name,items,value){return `<label>${esc(label)}<select name="${esc(name)}">${items.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`}
function pagination(action,page,pages){return `<div class="ow-pagination">${button('←',action,`data-page="${page-1}" ${page===0?'disabled':''} aria-label="Previous"`)}<span>${page+1}/${pages}</span>${button('→',action,`data-page="${page+1}" ${page===pages-1?'disabled':''} aria-label="Next"`)}</div>`}
function bindingControls(b){const s=pendingStatus(b),pending=pendingFor(b.agentId),c=b.connection;return `<div class="ow-popup-room"><div><strong>${esc(c?.label||b.connectionId)}</strong><small>${esc(s.label)}</small>${b.error?`<small>${esc(b.error)}</small>`:''}${c?.message?`<small>${esc(c.message)}</small>`:''}${c?.desired_state?`<small>Requested: ${esc(c.desired_state)}</small>`:''}</div>${b.canManage&&!pending&&!s.uncertain?button(s.connected?'Disconnect':'Connect','connection',`data-binding="${esc(b.key)}" data-verb="${s.connected?'disconnect':'connect'}" data-key="connection-${esc(b.key)}"`,'ow-button'+(s.connected?'':' ow-primary')):button('Refresh status','refresh-agent',`data-agent="${b.agentId}"`)} </div>`}
const forms=new Set(['attach','create-agent','create-machine','service-add','assign','pair-computer','disconnect-machine']);
function open(kind,trigger,values={}){returnKey=trigger?.dataset?.key||returnKey;modal=kind;draft=values;if(['assign','service-add'].includes(kind)){draft.endpoint_id=selected;draft.endpoint_revision=agent()?.endpoint.revision;if(kind==='service-add')draft.service_schema=structuredClone(catalogs[selected]?.data?.services?.find(s=>s.id===values.service_id))}renderPopup();const dialog=q('#ow-dialog');if(!dialog.open)dialog.showModal();(dialog.querySelector('input,select,[data-autofocus]')||dialog.querySelector('button'))?.focus({preventScroll:true})}
