 if(modal==='agent'&&a){const bs=model.bindings.filter(b=>b.agentId===a.id),m=machine(a.machineId),read=catalogs[a.id],pending=pendingFor(a.id);html=heading(a.name,m?.name)+`<div class="ow-profile-hero">${portrait(a.portrait)}<div><p>${esc(a.engine||'Runtime not reported')}</p><p class="ow-muted">${esc(when(read?.checkedAt))}</p>${button('Show computer','visit-computer',`data-machine="${a.machineId}"`,'ow-button ow-small')}</div></div>${read?.error?`<p class="ow-warning">${esc(read.error)}</p>`:''}${pending?`<p class="ow-warning">${pending.uncertain?'The last request was not confirmed. Refresh reads its status without sending it again.':'The installation is handling your request.'}</p>`:''}<h3>Places</h3><div class="ow-popup-rooms">${bs.map(b=>`<section>${button(mark(place(b.placeId))+esc(place(b.placeId)?.name),'enter',`data-place="${esc(b.placeId)}"`,'ow-place-link')}${bindingControls(b)}</section>`).join('')||'<p>No saved connections reported.</p>'}</div><div class="ow-dialog-actions">${button('Refresh','refresh-agent',`data-agent="${a.id}"`)}${button('Add a connection','connection-setup',`data-agent="${a.id}"`)}${button('Assign computer','assign',`data-agent="${a.id}"`)}${ownLink(a)}</div>`}
